import{_ as i,W as l,s as o,u as d,I as t,ah as r,w as n,Z as p,A as e}from"./chunks/framework.DRqsSc0o.js";import"./chunks/theme.DlTh90wK.js";const f=JSON.parse('{"title":"awk 系列：如何使用 awk 输出文本中的字段和列 | LCTT x X-CMD","titleTemplate":false,"description":"awk 系列：如何使用 awk 输出文本中的字段和列 | LCTT (awk) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"awk 系列：如何使用 awk 输出文本中的字段和列 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"awk 系列：如何使用 awk 输出文本中的字段和列 | LCTT (awk) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"awk/Part 2 - How to Use Awk to Print Fields and Columns in File","title":"awk 系列：如何使用 awk 输出文本中的字段和列","tag":"awk"},"relativePath":"awk/Part 2 - How to Use Awk to Print Fields and Columns in File.md","filePath":"[post].md"}'),u={name:"awk/Part 2 - How to Use Awk to Print Fields and Columns in File.md"};function m(w,s,c,k,h,g){const a=l("Link");return d(),o("div",null,[s[18]||(s[18]=t("h1",{id:"awk-系列-如何使用-awk-输出文本中的字段和列",tabindex:"-1"},[n("awk 系列：如何使用 awk 输出文本中的字段和列 "),t("a",{class:"header-anchor",href:"#awk-系列-如何使用-awk-输出文本中的字段和列","aria-label":"Permalink to awk 系列：如何使用 awk 输出文本中的字段和列"},"​")],-1)),s[19]||(s[19]=t("p",null,"在 Awk 系列的这一节中，我们将看到 awk 最重要的特性之一，字段编辑。",-1)),s[20]||(s[20]=t("p",null,"首先我们要知道，Awk 能够自动将输入的行，分隔为若干字段。每一个字段就是一组字符，它们和其他的字段由一个内部字段分隔符分隔开来。",-1)),s[21]||(s[21]=t("p",null,[t("img",{src:"http://www.tecmint.com/wp-content/uploads/2016/04/Awk-Print-Fields-and-Columns.png",alt:""})],-1)),s[22]||(s[22]=t("p",null,[t("em",null,"Awk 输出字段和列")],-1)),t("p",null,[s[1]||(s[1]=n("如果你熟悉 Unix/Linux 或者懂得 ")),p(a,{href:"http://www.tecmint.com/category/bash-shell/"},{default:e(()=>s[0]||(s[0]=[n("bash shell 编程")])),_:1}),s[2]||(s[2]=n("，那么你应该知道什么是内部字段分隔符（IFS）变量。awk 中默认的 IFS 是制表符和空格。"))]),s[23]||(s[23]=r(`<p>awk 中的字段分隔符的工作原理如下：当读到一行输入时，将它按照指定的 IFS 分割为不同字段，第一组字符就是字段一，可以通过 $1 来访问，第二组字符就是字段二，可以通过 $2 来访问，第三组字符就是字段三，可以通过 $3 来访问，以此类推，直到最后一组字符。</p><p>为了更好地理解 awk 的字段编辑，让我们看一个下面的例子：</p><p><strong>例 1</strong>：我创建了一个名为 tecmintinfo.txt 的文本文件。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># vi tecmintinfo.txt</span></span>
<span class="line"><span># cat tecmintinfo.txt</span></span></code></pre></div><p><img src="http://www.tecmint.com/wp-content/uploads/2016/04/Create-File-in-Linux.png" alt=""></p><p><em>在 Linux 上创建一个文件</em></p><p>然后在命令行中，我试着使用下面的命令从文本 tecmintinfo.txt 中输出第一个，第二个，以及第三个字段。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ awk &#39;//{print $1 $2 $3 }&#39; tecmintinfo.txt</span></span>
<span class="line"><span>TecMint.comisthe</span></span></code></pre></div><p>从上面的输出中你可以看到，前三个字段的字符是以空格为分隔符输出的：</p><ul><li>字段一是 “TecMint.com”，可以通过 <code>$1</code> 来访问。</li><li>字段二是 “is”，可以通过 <code>$2</code> 来访问。</li><li>字段三是 “the”，可以通过 <code>$3</code> 来访问。</li></ul><p>如果你注意观察输出的话可以发现，输出的字段值并没有被分隔开，这是 print 函数默认的行为。</p><p>为了使输出看得更清楚，输出的字段值之间使用空格分开，你需要添加 (,) 操作符。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ awk &#39;//{print $1, $2, $3; }&#39; tecmintinfo.txt</span></span>
<span class="line"><span></span></span>
<span class="line"><span>TecMint.com is the</span></span></code></pre></div><p>需要记住而且非常重要的是，<code>($)</code> 在 awk 和在 shell 脚本中的使用是截然不同的！</p><p>在 shell 脚本中，<code>($)</code> 被用来获取变量的值。而在 awk 中，<code>($)</code> 只有在获取字段的值时才会用到，不能用于获取变量的值。</p><p><strong>例 2</strong>：让我们再看一个例子，用到了一个名为 my_shoping.list 的包含多行的文件。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>No	  Item_Name		            Unit_Price	Quantity	Price</span></span>
<span class="line"><span>1	    Mouse			              #20,000		   1		    #20,000</span></span>
<span class="line"><span>2 	    Monitor			            #500,000	   1		    #500,000</span></span>
<span class="line"><span>3	    RAM_Chips		            #150,000	   2		    #300,000</span></span>
<span class="line"><span>4	    Ethernet_Cables	        #30,000		   4		    #120,000</span></span></code></pre></div><p>如果你只想输出购物清单上每一个物品的<code>单价</code>，你只需运行下面的命令：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ awk &#39;//{print $2, $3 }&#39; my_shopping.txt </span></span>
<span class="line"><span></span></span>
<span class="line"><span>Item_Name Unit_Price</span></span>
<span class="line"><span>Mouse #20,000</span></span>
<span class="line"><span>Monitor #500,000</span></span>
<span class="line"><span>RAM_Chips #150,000</span></span>
<span class="line"><span>Ethernet_Cables #30,000</span></span></code></pre></div><p>可以看到上面的输出不够清晰，awk 还有一个 <code>printf</code> 的命令，可以帮助你将输出格式化。</p><p>使用 <code>printf</code> 来格式化 Item_Name 和 Unit_Price 的输出：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ awk &#39;//{printf &quot;%-10s %s\\n&quot;,$2, $3 }&#39; my_shopping.txt </span></span>
<span class="line"><span></span></span>
<span class="line"><span>Item_Name  Unit_Price</span></span>
<span class="line"><span>Mouse      #20,000</span></span>
<span class="line"><span>Monitor    #500,000</span></span>
<span class="line"><span>RAM_Chips  #150,000</span></span>
<span class="line"><span>Ethernet_Cables #30,000</span></span></code></pre></div><h3 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to 总结">​</a></h3><p>使用 awk 过滤文本或字符串时，字段编辑的功能是非常重要的。它能够帮助你从一个表的数据中得到特定的列。一定要记住的是，awk 中 <code>($)</code> 操作符的用法与其在 shell 脚本中的用法是不同的！</p><p>希望这篇文章对您有所帮助。如有任何疑问，可以在评论区域发表评论。</p><hr>`,26)),t("p",null,[s[4]||(s[4]=n("via: ")),p(a,{href:"http://www.tecmint.com/awk-print-fields-columns-with-space-separator/"},{default:e(()=>s[3]||(s[3]=[n("http://www.tecmint.com/awk-print-fields-columns-with-space-separator/")])),_:1})]),t("p",null,[s[9]||(s[9]=n("作者：")),p(a,{href:"http://www.tecmint.com/author/aaronkili/"},{default:e(()=>s[5]||(s[5]=[n("Aaron Kili")])),_:1}),s[10]||(s[10]=n(" 译者：")),p(a,{href:"https://github.com/Cathon"},{default:e(()=>s[6]||(s[6]=[n("Cathon")])),_:1}),s[11]||(s[11]=n("，")),p(a,{href:"https://github.com/ictlyh"},{default:e(()=>s[7]||(s[7]=[n("ictlyh")])),_:1}),s[12]||(s[12]=n(" 校对：")),p(a,{href:"https://github.com/wxy"},{default:e(()=>s[8]||(s[8]=[n("wxy")])),_:1})]),t("p",null,[s[15]||(s[15]=n("本文由 ")),p(a,{href:"https://github.com/LCTT/TranslateProject"},{default:e(()=>s[13]||(s[13]=[n("LCTT")])),_:1}),s[16]||(s[16]=n(" 原创编译，")),p(a,{href:"https://linux.cn/"},{default:e(()=>s[14]||(s[14]=[n("Linux中国")])),_:1}),s[17]||(s[17]=n(" 荣誉推出"))])])}const v=i(u,[["render",m]]);export{f as __pageData,v as default};
